DROP TABLE IF EXISTS `taxi_path_node`;
CREATE TABLE `taxi_path_node` (
    `ID` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `PathNode` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `NodeIndex` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `MapID` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `PositionX` FLOAT NOT NULL DEFAULT '0',
    `PositionY` FLOAT NOT NULL DEFAULT '0',
    `PositionZ` FLOAT NOT NULL DEFAULT '0',
    `ActionFlags` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `Delay` INT(10) UNSIGNED NOT NULL DEFAULT '0',
    `ArrivalEventID` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `DepartureEventID` MEDIUMINT(8) UNSIGNED NOT NULL DEFAULT '0',
    `VerifiedBuild` SMALLINT(5) NOT NULL DEFAULT '0',
    PRIMARY KEY (`ID`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

